def cosine_similarity(a, b):
    dot = (a * b).sum()
    norm_a = torch.sqrt((a * a).sum())
    norm_b = torch.sqrt((b * b).sum())
    return dot / (norm_a * norm_b)

def word_error_rate(hypothesis, reference):
    # Levenshtein distance
    import numpy as np
    hyp = hypothesis.split()
    ref = reference.split()
    n = len(hyp)
    m = len(ref)
    dp = np.zeros((n+1, m+1))
    for i in range(n+1):
        dp[i][0] = i
    for j in range(m+1):
        dp[0][j] = j
    for i in range(1, n+1):
        for j in range(1, m+1):
            cost = 0 if hyp[i-1] == ref[j-1] else 1
            dp[i][j] = min(dp[i-1][j] + 1, dp[i][j-1] + 1, dp[i-1][j-1] + cost)
    return dp[n][m] / max(len(ref), 1)

def fid(mu1, sigma1, mu2, sigma2):
    diff = mu1 - mu2
    covmean = torch.sqrt(torch.mm(sigma1, sigma2))
    return diff.dot(diff) + torch.trace(sigma1 + sigma2 - 2*covmean)

def mean_iou(preds, target, num_classes):
    iou = []
    for cls in range(num_classes):
        intersection = ((preds == cls) & (target == cls)).sum().float()
        union = ((preds == cls) | (target == cls)).sum().float()
        iou.append(intersection / (union + 1e-8))
    return torch.tensor(iou).mean()
